import java.util.Scanner;
public class Program
{
	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int amount = scanner.nextInt();
        int res= amount;
		 for(int x=0;x<=2;x++){
           res=(int) (res*0.9);
        }
        System.out.println(res);
	}
}
